import Image from "next/image";
import ClientLayout from "../components/ClientLayout";
import { getDictionary } from "../../../lib/getDictionary";
import CallToAction from "../components/CallToAction";

export async function generateMetadata({ params: { locale } }) {
  const dict = await getDictionary(locale);

  return {
    title: dict.solution.title,
    description: dict.solution.description,
    keywords:
      "FutureVerde, ESG reporting, green finance, AI-powered sustainability, ESG analysis, sustainability platform, green financing solutions, ESG compliance",
    openGraph: {
      title: dict.solution.title,
      description: dict.solution.description,
      type: "website",
      locale: locale,
      alternateLocale: locale === "en" ? "tr" : "en",
      url: `https://futureverde.com/${locale}/solution`,
      images: [
        {
          url: `https://futureverde.com/images/solution-futureverde.jpg`,
          width: 1200,
          height: 630,
        },
      ],
    },
    twitter: {
      card: "summary_large_image",
      title: dict.solution.title,
      description: dict.solution.description,
      images: ["https://futureverde.com/images/solution-futureverde.jpg"],
    },
    alternates: {
      canonical: `https://futureverde.com/${locale}/solution`,
      languages: {
        en: "https://futureverde.com/en/solution",
        tr: "https://futureverde.com/tr/solution",
      },
    },
    robots: {
      index: true,
      follow: true,
    },
  };
}

